const hash = (value: string): string => createHash("sha256").update(value).digest("hex");
async function tx<T>(pool: PersistencePool, work: (client: PersistenceClient) => Promise<T>): Promise<T> { const client = await pool.connect(); try { await client.query("BEGIN"); const result = await work(client); await client.query("COMMIT"); return result; } catch (error) { await client.query("ROLLBACK"); throw error; } finally { client.release(); } }
function parseTrainerTrigger(payload: unknown): TrainerTrigger { if (!payload || typeof payload !== "object") throw new Error("TLS_DAY2_TRAINER_PAYLOAD_REQUIRED"); const value = payload as Readonly<Record<string, unknown>>; if (typeof value["ticketId"] !== "string" || value["ticketId"].length === 0) throw new Error("TLS_DAY2_TRAINER_TICKET_REQUIRED"); if (typeof value["scenarioRunRef"] !== "string" || value["scenarioRunRef"].length === 0) throw new Error("TLS_DAY2_SCENARIO_RUN_REQUIRED"); return Object.freeze({ ticketId: value["ticketId"], scenarioRunRef: value["scenarioRunRef"] }); }

async function runtimeRow(client: PersistenceClient, ticketId: string): Promise<RuntimeRow> {
  const result = await client.query<RuntimeRow>(`SELECT rt.current_state_code,rt.aggregate_version::text,rt.activation_record_ref::text,rt.purpose_binding_id::text,ra.responsibility_id::text,ra.holder_ref::text FROM appts.runtime_ticket rt JOIN appts.responsible_assignment ra ON ra.ticket_id=rt.ticket_id AND ra.effective_to IS NULL WHERE rt.ticket_id=$1 ORDER BY ra.effective_from DESC LIMIT 1`, [ticketId]);
  if (!result.rowCount) throw new Error("TLS_DAY2_RUNTIME_TICKET_NOT_FOUND"); return result.rows[0]!;
}
async function latestStageRefs(client: PersistenceClient, ticketId: string): Promise<StageRefs | undefined> {
  const result = await client.query<{ qer_id: string; external_record_identity: string; payload: unknown; evidence_id: string; qualification_id: string; evidence_set_id: string; verification_request_id: string | null; verification_result_id: string | null }>(`SELECT q.qualified_external_record_id::text AS qer_id,q.external_record_identity,q.payload_or_reference_ref_json AS payload,eo.evidence_id::text,eq.qualification_id::text,es.evidence_set_version_id::text AS evidence_set_id,vrq.verification_request_id::text,vr.verification_result_id::text FROM appts.qualified_external_record q JOIN appts.evidence_object eo ON eo.ticket_id=q.ticket_id AND eo.source_context_ref->>'qualified_external_record_id'=q.qualified_external_record_id::text JOIN appts.evidence_qualification eq ON eq.evidence_id=eo.evidence_id JOIN appts.evidence_set_member esm ON esm.evidence_id=eo.evidence_id AND esm.qualification_id=eq.qualification_id JOIN appts.evidence_set_version es ON es.evidence_set_version_id=esm.evidence_set_version_id LEFT JOIN LATERAL (SELECT verification_request_id FROM appts.verification_request v WHERE v.ticket_id=q.ticket_id AND v.evidence_set_version_id=es.evidence_set_version_id ORDER BY v.requested_at DESC LIMIT 1) vrq ON true LEFT JOIN LATERAL (SELECT verification_result_id FROM appts.verification_result v WHERE v.verification_request_id=vrq.verification_request_id ORDER BY v.completed_at DESC LIMIT 1) vr ON true WHERE q.ticket_id=$1 AND q.source_system_ref_id=$2 ORDER BY q.received_at DESC LIMIT 1`, [ticketId, D2_SOURCE_SYSTEM]);
  if (!result.rowCount) return undefined; const row = result.rows[0]!; const payload = row.payload && typeof row.payload === "object" ? row.payload as Readonly<Record<string, unknown>> : {}; const scenarioRunRef = typeof payload["scenario_run_ref"] === "string" ? payload["scenario_run_ref"] : "UNKNOWN";
  return Object.freeze({ qerId: row.qer_id, evidenceId: row.evidence_id, qualificationId: row.qualification_id, evidenceSetId: row.evidence_set_id, scenarioRunRef, externalRecordIdentity: row.external_record_identity, ...(row.verification_request_id ? { verificationRequestId: row.verification_request_id } : {}), ...(row.verification_result_id ? { verificationResultId: row.verification_result_id } : {}) });
}
