  await client.query(`INSERT INTO appts.progression_envelope(record_version,domain_id,purpose_binding_id,source_ref_id,source_version_ref_id,observed_at,received_at,committed_at,actor_ref,authority_ref,qualification_ref,disclosure_label_ref,correlation_id,envelope_id,gate_evaluation_id,ticket_id,effective_from,currentness_ref) VALUES(1,$1,$2,$3,$4,$5,$5,$5,$6,$7,$8,$9,$10,$11,$12,$13,$5,'CURRENT')`, [DOMAIN,PURPOSE_BINDING,D2_SOURCE_REF,D2_SOURCE_VERSION,at,input.actor.holder,authorityResult,QUALIFICATION_REF,DISCLOSURE,randomUUID(),progressionEnvelope,gateEvaluation,input.ticketId]);
