    await client.query(`INSERT INTO appts.qualified_external_record(record_version,ticket_id,domain_id,purpose_binding_id,source_ref_id,source_version_ref_id,observed_at,effective_from,committed_at,qualification_ref,disclosure_label_ref,correlation_id,qualified_external_record_id,source_system_ref_id,external_record_identity,external_record_version_ref,subject_ref,qualification_result_ref,source_time,received_at,payload_or_reference_ref_kind,payload_or_reference_ref_json,payload_or_reference_ref_json_schema_version,payload_hash,currentness_ref) VALUES(1,$1,$2,$3,$4,$5,$6,$6,$6,$7,$8,$9,$10,$11,$12,'1',$13,'PROVISIONAL_PENDING_VERIFICATION',$6,$6,'JSON',$14::jsonb,'1.0.0',$15,'CURRENT')`, [trigger.ticketId,DOMAIN,PURPOSE_BINDING,D2_SOURCE_REF,D2_SOURCE_VERSION,at,QUALIFICATION_REF,DISCLOSURE,randomUUID(),qerId,D2_SOURCE_SYSTEM,externalRecordIdentity,SUBJECT,JSON.stringify(eventPayload),qer.payload_hash]);
    const evidenceId = randomUUID(); const qualificationId = randomUUID(); const evidenceSetId = randomUUID(); const priorSet = await client.query<{ evidence_set_version_id: string; set_version: string }>("SELECT evidence_set_version_id::text,set_version::text FROM appts.evidence_set_version WHERE ticket_id=$1 ORDER BY set_version DESC LIMIT 1",[trigger.ticketId]); const nextSetVersion = Number(priorSet.rows[0]?.set_version ?? 0)+1; const ev = {evidenceId,sourceRef:qerId,contentDigest:qer.payload_hash??hash(externalRecordIdentity),observedAt:at,qualification:"SUFFICIENT" as const,retainUntil:"TRIAL_CONTROLLED_RETENTION"}; recordEvidence(ev); versionEvidenceSet(evidenceSetId,nextSetVersion,[ev],priorSet.rows[0]?.evidence_set_version_id);
    await client.query(`INSERT INTO appts.evidence_object(record_version,ticket_id,domain_id,purpose_binding_id,source_ref_id,source_version_ref_id,observed_at,received_at,committed_at,qualification_ref,disclosure_label_ref,correlation_id,evidence_id,subject_type,subject_id,evidence_type_ref,source_context_ref,source_context_ref_schema_version,content_ref_kind,content_ref_json,content_ref_json_schema_version,availability_ref,retention_obligation_ref) VALUES(1,$1,$2,$3,$4,$5,$6,$6,$6,$7,$8,$9,$10,'SERVICE',$11,'SERVICE_RESTORATION_INDICATION',$12::jsonb,'1.0.0','JSON',$13::jsonb,'1.0.0','AVAILABLE',$14)`, [trigger.ticketId,DOMAIN,PURPOSE_BINDING,D2_SOURCE_REF,D2_SOURCE_VERSION,at,QUALIFICATION_REF,DISCLOSURE,randomUUID(),evidenceId,SUBJECT,JSON.stringify({qualified_external_record_id:qerId,scenario_run_ref:trigger.scenarioRunRef,provisional:true}),JSON.stringify(eventPayload),randomUUID()]);
