function parseAction(payload: unknown): ActionIntentPayload { const validation = validateActionIntent(payload); if (!validation.ok) throw new Error(`TLS_DAY2_INVALID_ACTION_INTENT:${validation.issues.map((item)=>item.code).join(",")}`); return payload as ActionIntentPayload; }
async function currentActionContext(client: PersistenceClient,ticketId:string): Promise<CurrentActionContext> { const result = await client.query<{aggregate_version:string;current_state_code:RuntimeAggregate["state"];authority_projection_id:string;gate_projection_id:string;authority_result_id:string;gate_result_id:string;action_class_ref:string|null;availability_result_ref:string|null;responsible_assignment_ref:string;authority_currentness:string;gate_currentness:string}>(`SELECT rt.aggregate_version::text,rt.current_state_code,ap.authority_projection_id::text,gp.gate_projection_id::text,ap.source_authority_result_id::text AS authority_result_id,gp.source_gate_result_id::text AS gate_result_id,m.action_class_ref,m.availability_result_ref,ap.responsible_assignment_ref::text,ap.currentness_ref AS authority_currentness,gp.currentness_ref AS gate_currentness FROM appts.runtime_ticket rt JOIN appts.authority_projection ap ON ap.authority_projection_id=rt.current_authority_projection_id JOIN appts.gate_projection gp ON gp.gate_projection_id=rt.current_gate_projection_id LEFT JOIN LATERAL (SELECT m.action_class_ref,m.availability_result_ref FROM appts.action_set_snapshot s JOIN appts.action_set_member m ON m.action_set_snapshot_id=s.action_set_snapshot_id WHERE s.ticket_id=rt.ticket_id AND s.aggregate_version=rt.aggregate_version ORDER BY s.derived_at DESC,m.action_set_member_id DESC LIMIT 1) m ON true WHERE rt.ticket_id=$1`,[ticketId]); if(!result.rowCount) throw new Error("TLS_DAY2_ACTION_CONTEXT_NOT_FOUND"); const row=result.rows[0]!; return Object.freeze({aggregateVersion:Number(row.aggregate_version),state:row.current_state_code,authorityProjection:row.authority_projection_id,gateProjection:row.gate_projection_id,authorityResult:row.authority_result_id,gateResult:row.gate_result_id,actionClass:row.action_class_ref,actionAvailability:row.availability_result_ref,actionAssignment:row.responsible_assignment_ref,authorityCurrentness:row.authority_currentness,gateCurrentness:row.gate_currentness}); }
async function validatePresentedAction(client:PersistenceClient,intent:ActionIntentPayload,actor:{holder:string;assignment:string},action:string):Promise<CurrentActionContext>{ const context=await currentActionContext(client,intent.ticket_id); if(context.state!=="ACTIVE") throw new Error("TLS_DAY2_ACTION_REQUIRES_ACTIVE_TICKET"); if(context.aggregateVersion!==intent.expected_aggregate_version) throw new Error("TLS_DAY2_STALE_AGGREGATE"); if(context.authorityCurrentness!=="CURRENT"||context.gateCurrentness!=="CURRENT") throw new Error("TLS_DAY2_NONCURRENT_AUTHORITY_OR_GATE"); if(intent.actor_ref!==actor.holder||intent.role_assignment_ref!==actor.assignment) throw new Error("TLS_DAY2_ACTOR_ROLE_BINDING_MISMATCH"); if(context.actionClass!==action||context.actionAvailability!=="AVAILABLE") throw new Error("TLS_DAY2_ACTION_NOT_PRESENTED"); if(context.actionAssignment!==actor.assignment) throw new Error("TLS_DAY2_ACTION_ASSIGNMENT_MISMATCH"); return context; }

async function requestVerification(pool:PersistencePool,payload:unknown):Promise<unknown>{ const intent=parseAction(payload); if(intent.requested_action_class!==TLS_DAY2_REQUEST_VERIFICATION) throw new Error("TLS_DAY2_REQUEST_ACTION_MISMATCH"); return tx(pool,async(client)=>{ if(await priorActionResult(client,intent.action_intent_id)) return Object.freeze({result:"ACK",durable:true,replay:true,ticketId:intent.ticket_id,state:"ACTIVE"}); await validatePresentedAction(client,intent,ROLE.responsible,TLS_DAY2_REQUEST_VERIFICATION); const refs=await latestStageRefs(client,intent.ticket_id); if(!refs) throw new Error("TLS_DAY2_EVIDENCE_REQUIRED_BEFORE_VERIFICATION_REQUEST"); if(refs.verificationRequestId) return Object.freeze({result:"ACK",durable:true,replay:true,ticketId:intent.ticket_id,state:"ACTIVE",verificationRequestId:refs.verificationRequestId}); await recordIntent(client,intent); const at=now(); const requestId=randomUUID(); await client.query(`INSERT INTO appts.verification_request(record_version,domain_id,purpose_binding_id,source_ref_id,source_version_ref_id,observed_at,received_at,committed_at,actor_ref,authority_ref,qualification_ref,disclosure_label_ref,correlation_id,verification_request_id,ticket_id,scope_ref,scope_ref_schema_version,evidence_set_version_id,required_independence_ref,requested_verifier_role_ref,requested_at,method_ref) VALUES(1,$1,$2,$3,$4,$5,$5,$5,$6,$7,$8,$9,$10,$11,$12,$13::jsonb,'1.0.0',$14,'INDEPENDENT_REQUIRED',$15,$5,'CONTROLLED_TRIAL_RESTORATION_VERIFICATION')`, [DOMAIN,PURPOSE_BINDING,D2_SOURCE_REF,D2_SOURCE_VERSION,at,ROLE.responsible.holder,randomUUID(),QUALIFICATION_REF,DISCLOSURE,randomUUID(),requestId,intent.ticket_id,JSON.stringify({scenario:TLS_DAY2_SCENARIO,scenario_run_ref:refs.scenarioRunRef,evidence_set:refs.evidenceSetId}),refs.evidenceSetId,ROLE.verifier.roleInstance]); await client.query(`INSERT INTO appts.next_control(ticket_id,aggregate_version,control_class_ref,owner_or_responsibility_ref,source_obligation_ref,effective_at,currentness_ref) VALUES($1,$2,'INDEPENDENT_VERIFICATION_EXECUTION_REQUIRED',$3,$4,$5,'CURRENT')`, [intent.ticket_id,intent.expected_aggregate_version,ROLE.verifier.symbolicRole,requestId,at]); await createActionContext(client,{ticketId:intent.ticket_id,actor:ROLE.verifier,actionClass:TLS_DAY2_VERIFY_EVIDENCE,availability:"AVAILABLE",gateResult:"VERIFICATION_REQUEST_CURRENT",evidenceSetId:refs.evidenceSetId}); return Object.freeze({result:"ACK",durable:true,replay:false,ticketId:intent.ticket_id,state:"ACTIVE",verificationRequestId:requestId,nextRole:ROLE.verifier.symbolicRole}); }); }

