async function findDurableEffectResult(pool:PersistencePool,commandId:string):Promise<DurableEffectResult|undefined>{ const result=await pool.query<{command_id:string;result_hash:string|null;effect_disposition_code:string;reason_ref:string|null;resulting_aggregate_version:string|null;current_state_code:RuntimeAggregate["state"]}>(`SELECT r.command_id::text,m.result_hash,e.effect_disposition_code,e.reason_ref,e.resulting_aggregate_version::text,rt.current_state_code FROM appts.lifecycle_effect_request r JOIN appts.lifecycle_effect_result e ON e.effect_request_id=r.effect_request_id JOIN appts.commit_marker m ON m.commit_marker_id=e.durable_commit_marker_id JOIN appts.runtime_ticket rt ON rt.ticket_id=r.ticket_id WHERE r.command_id=$1`,[commandId]); if(!result.rowCount)return undefined;const row=result.rows[0]!;return Object.freeze({commandId:row.command_id,payloadHash:row.result_hash??"",disposition:row.effect_disposition_code as DurableEffectResult["disposition"],reason:row.reason_ref??"",aggregateVersion:Number(row.resulting_aggregate_version??0),state:row.current_state_code,auditRef:`audit:${commandId}`}); }
